"""Point Lines: keep the new operation visible, provide the full working script."""
from pathlib import Path
import difflib
import hashlib
import html
import json
import re
import xml.etree.ElementTree as ET
import markdown

OUT = Path(__file__).resolve().parent
ROOT = OUT.parents[3]
STARTER = ROOT / 'doc/book/studies/ada-xr-starter'
SOURCE = ROOT / 'commons/maps/Point_Lines/tutorial.md'
after = SOURCE.read_text(encoding='utf-8')
before = (OUT / 'before/tutorial.md').read_text(encoding='utf-8')
code = (STARTER / 'studies/point_lines/line.gd').read_text(encoding='utf-8')
blocks = re.findall(r'```gdscript\n(.*?)```', after, re.S)
assert len(blocks) == 4
for block in blocks:
    assert block.strip() in code
assert '$' not in code and 'get_node' not in code and 'NodePath' not in code
assert '"res://prepared/point_handle.gd"' in code and '"res://prepared/segment.gd"' in code
reference = ET.parse(ROOT.parent / 'godot_reference_4.6/doc/classes/Vector3.xml').getroot()
assert reference.find("methods/method[@name='length']/return").get('type') == 'float'
assert reference.find("operators/operator[@name='operator -']/return").get('type') == 'Vector3'
check = json.loads((OUT / 'verification.json').read_text())
assert check['passed']
(OUT / 'line.gd').write_text(code, encoding='utf-8')
for name in ('point_handle.gd', 'segment.gd'):
    (OUT / name).write_text((STARTER / 'prepared' / name).read_text(), encoding='utf-8')
(OUT / 'Point_Lines.tutorial.md').write_text(after, encoding='utf-8')
(OUT / 'Point_Lines.tutorial.diff').write_text(''.join(difflib.unified_diff(before.splitlines(True), after.splitlines(True), fromfile='before/Point_Lines/tutorial.md', tofile='commons/maps/Point_Lines/tutorial.md')), encoding='utf-8')
contract = {'map':'Point_Lines','status':'author_review_pilot','inherits':['Point Zero: variables, ready/process, Label3D, str()','Point One: position and marker construction','Coordinates: common reference frame and supplied hold'], 'introduces':['two positions in one frame','vector subtraction returns a displacement','length() returns a float distance','const/preload name supplied scripts','two-decimal string formatting displays a measured value'], 'supplied':['PointHandle: XR Tools pickup and frozen release','Segment: midpoint, orientation, radius and near-zero handling','Day Zero room, light and player'], 'learner_actions':['change one coordinate','turn without lengthening','reverse displacement','hold and move an endpoint','coincide and separate endpoints','compare identical endpoints after a detour'], 'next':'Trace: retain the positions in between', 'coordinates_rewrite_pending':True, 'printed_code_matches_download':True, 'source_sha256':hashlib.sha256(SOURCE.read_bytes()).hexdigest(), 'physical_headset_tested':False}
(OUT / 'lesson-contract.json').write_text(json.dumps(contract,indent=2)+'\n',encoding='utf-8')
reading = markdown.markdown(after.replace('../../../doc/book/studies/ada-xr-starter/README.md','../2026-10-03-ada-xr-starter/index.html#guide'),extensions=['fenced_code'])
reading = reading.replace('<h2>1. Keep two positions</h2>', '<figure><a href="room.png"><img src="room.png" alt="Two pale grabbable points joined by a horizontal segment, with displacement and distance above, inside the shared Godot room"></a><figcaption>Actual Godot render. The upper reading is the displacement; below it is the distance.</figcaption></figure><h2>1. Keep two positions</h2>')
reading = reading.replace('<h2>4. Read it while it changes</h2>', '<div class="pair"><figure><a href="upright.png"><img src="upright.png" alt="The segment is vertical and its distance remains 1.5 metres" loading="lazy"></a><figcaption>Turned upright · the distance remains 1.5 m.</figcaption></figure><figure><a href="depth.png"><img src="depth.png" alt="One endpoint has moved in height and depth, producing a diagonal segment" loading="lazy"></a><figcaption>Change height and depth · all three components contribute.</figcaption></figure></div><h2>4. Read it while it changes</h2>')
style='''*{box-sizing:border-box}body{margin:0;background:#f5f1e9;color:#29282b;font:19px/1.65 Georgia,serif}main{max-width:1160px;margin:auto;padding:30px 26px 70px}header{border-bottom:1px solid #cdc6bd;padding-bottom:22px;font:14px/1.6 system-ui,sans-serif}nav{display:flex;gap:12px 24px;flex-wrap:wrap}a{color:#84445f;text-underline-offset:4px}article{max-width:760px;margin:48px auto}h1{font-size:clamp(32px,4vw,47px);font-weight:normal;line-height:1.18}h2{font-size:29px;font-weight:normal;margin-top:44px}p{margin:0 0 23px}code{font:.84em Consolas,monospace}pre{background:#e9e3db;border-left:3px solid #b87792;padding:22px;overflow-x:auto;font:15px/1.6 Consolas,monospace}pre code{font:inherit}figure{margin:34px -90px}img{width:100%;height:auto;display:block}figcaption,.small{font:14px/1.6 system-ui,sans-serif;color:#5e575b;margin-top:12px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:30px -100px}.pair figure{margin:0;min-width:0}details{margin:28px 0;border-top:1px solid #cdc6bd;padding-top:20px}summary{cursor:pointer;font:17px/1.5 system-ui,sans-serif}details>div{max-width:760px;margin:20px auto}.download{display:inline-block;background:#733e55;color:white;padding:10px 20px;text-decoration:none;font:16px/1.5 system-ui,sans-serif;border-radius:3px}.lineage{max-width:760px;margin:45px auto;border-top:1px solid #cdc6bd;padding-top:20px}a:focus-visible,summary:focus-visible{outline:3px solid #aa577b;outline-offset:4px}@media(max-width:1000px){figure,.pair{margin:30px 0}}@media(max-width:650px){.pair{grid-template-columns:1fr}main{padding:24px 17px}body{font-size:18px}pre{font-size:13px;padding:14px}}@media print{header,details,.download{display:none}body{background:white;font-size:11pt}figure,.pair{margin:20px 0}pre{white-space:pre-wrap}h2{break-after:avoid}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Point Lines — two ends</title><style>{style}</style></head><body><main><header><p>ADA / ONE TUTORIAL AT A TIME · 3 October 2026</p><nav><a href="#reading">Read Point Lines</a><a href="#code">Complete script</a><a href="#lineage">What it adds</a><a href="Point_Lines.tutorial.diff">Text diff</a></nav></header><article id="reading">{reading}<p><a class="download" href="../2026-10-03-ada-xr-starter/ada-xr-starter.zip" download>Download the starter with Point Lines</a></p><p class="small">Open point_lines.tscn · Run Current Scene (F6).</p></article><details id="code"><summary>line.gd · the complete working lesson</summary><div><pre><code>{html.escape(code)}</code></pre><p><a href="line.gd" download>Download line.gd</a> · <a href="point_handle.gd">Supplied point handle</a> · <a href="segment.gd">Supplied segment renderer</a></p></div></details><section id="lineage" class="lineage"><h2>The relation is the new work.</h2><p>The lesson inherits a position, a visible body and a working hold. It adds subtraction and length, then reads them repeatedly as the endpoints move. Trace will keep the positions that this calculation replaces.</p><p>Coordinates remains between Point One and Lines in the spine. Its shared-starter rewrite is still pending. This pilot supplies the hold and states the common reference frame explicitly.</p><p class="small">The critical manuscript and live museum are unchanged. This pass updates tutorial.md and its executable companion.</p></section><details id="checked"><summary>{len(check['checks'])} checks passed · scope and limits</summary><div><p>Checked in Godot 4.6: initial placement, length after coordinate edits, vertical and downward segments, depth, coinciding endpoints, desktop pickup and frozen release, synthetic XR grip, and the reversed subtraction. The lesson constructs its nodes without prepared teaching objects.</p><p>These are desktop renders. Synthetic controller input does not certify headset reach or comfort. A beginner reading trial is also pending.</p><p><a href="verification.json">Native results</a> · <a href="lesson-contract.json">Teaching scope</a> · <a href="DECISIONS.md">Editorial decisions</a></p></div></details></main><script>function reveal(){{const el=document.getElementById(location.hash.slice(1));if(el?.tagName==='DETAILS')el.open=true}}addEventListener('hashchange',reveal);reveal();</script></body></html>'''
(OUT / 'index.html').write_text(page,encoding='utf-8')
print(json.dumps({'words_including_code':len(after.split()),'native_checks':len(check['checks']),'printed_code_matches':True}))
